export const MOTION_KEY='meijing-portfolio-motion-v1';
export const pageLabels=['个人介绍','50+ App','纸跃 Agent','用户增长案例','AI 动作分析','My Skills','联系方式'];
const labels={1:{decor:'星星与装饰',portrait:'人物肖像',flowers:'花朵', 'portfolio-copy.png':'页面文字'},2:{'page-2-1':'手机拼图','page-2-2':'50+ App 标题','page-2-3':'勾选图标','portfolio-copy.png':'页面文字'},3:{'page-3-1':'右侧手机展示'},4:{'page-4-1':'右侧底纹','page-4-2':'正文纸张','page-4-3':'扩音器、计算器与手','page-4-4':'左侧手机展示','portfolio-copy.png':'页面文字'},5:{'page-5-1':'紫色底图','page-5-2':'顶部人物与装饰','page-5-3':'App 截图卡片','portfolio-copy.png':'页面文字'},6:{'page-6-1':'放射背景','page-6-2':'笔记本电脑','portfolio-copy.png':'My Skills 标题'},7:{'page-7-1':'握手插画','page-7-2':'联系图标','portfolio-copy.png':'联系文字'}};
export function motionDefaults(view){
 return {version:1,pages:view.pageMaterials.map((mat,i)=>{
  const number=i+1,names=mat.userData.layerNames;
  const groups=names.slice(1).map((name,index)=>({id:name,label:labels[number]?.[name]||name,layers:[name],x:mat.moveFactors[index+1].x,y:mat.moveFactors[index+1].y,src:window.__portfolioLayers[number]?.[name]?.startsWith('data:')?'/portfolio/profile/star.png':window.__portfolioLayers[number]?.[name]||null}));
  if(number===3){
   const members=['page-3-2','page-3-3','portfolio-copy.png'];
   for(let i=groups.length-1;i>=0;i--)if(members.includes(groups[i].id))groups.splice(i,1);
   groups.unshift({id:'left-collage',label:'左侧整组：纸张、贴纸、电脑、手机与文字',layers:members,x:.8,y:.4,src:'/portfolio/artwork-3.png'});
  }
  return {number,label:pageLabels[i],turn:number===1?1:number===2?.35:.12,pointer:1,ambient:.1,groups};
 })};
}
export function normalizeMotion(input,defaults){
 if(input?.version!==1||!Array.isArray(input.pages)||input.pages.length!==7)throw Error('请导入版本 1 的完整七页动效配置');
 const numeric=(value,min,max)=>{if(typeof value!=='number'||!Number.isFinite(value))throw Error('移动参数必须是有效数字');return Math.max(min,Math.min(max,value));};
 const result=structuredClone(defaults);
 for(const p of result.pages){const source=input.pages.find(s=>s.number===p.number);if(!source)throw Error('配置缺少第 '+p.number+' 页');p.turn=numeric(source.turn,0,2);p.pointer=numeric(source.pointer,0,3);p.ambient=numeric(source.ambient,0,1);
  for(const group of p.groups){const g=source.groups?.find(g=>g.id===group.id);if(!g)throw Error('配置缺少素材组：'+group.label);group.x=numeric(g.x,-3,3);group.y=numeric(g.y,-3,3);}
 }return result;
}
export function readMotion(defaults){try{const saved=localStorage.getItem(MOTION_KEY);return saved?normalizeMotion(JSON.parse(saved),defaults):structuredClone(defaults);}catch{return structuredClone(defaults);}}
